TERMS = [
# ============================ SOFTWARE ENGINEERING ============================
{"term": "Version Control", "branch": "Software Engineering", "de": "Versionsverwaltung", "aliases": ["VCS", "Source Control"],
 "tags": ["fundamental"], "wikipedia": "Version control",
 "def": "A system that records changes to files over time so you can recall any version, branch, merge, and collaborate without overwriting each other's work.",
 "context": "Distributed VCS (Git) won decisively over centralised (SVN, CVS): everyone has the full history, commits are local and cheap, branching is trivial. The conceptual model — a DAG of immutable snapshots — is worth understanding beneath the porcelain commands.",
 "see_also": ["Git", "Commit", "Branch", "Merge", "Repository"]},

{"term": "Git", "branch": "Software Engineering", "tags": ["fundamental"], "wikipedia": "Git",
 "def": "The dominant distributed version control system — a content-addressed store of immutable snapshots, where branches are cheap movable pointers into a commit DAG.",
 "context": "The mental model that makes Git click: it's a DAG of commits, each a snapshot identified by a hash; branches and tags are just labels on commits; the index/staging area is the third state between working tree and history. Once that lands, the commands stop feeling arbitrary.",
 "see_also": ["Version Control", "Commit", "Branch", "Merge", "Rebase", "Staging Area"]},

{"term": "Commit", "branch": "Software Engineering", "tags": ["fundamental"], "wikipedia": "Commit (version control)",
 "def": "A recorded snapshot of changes with a message, author, timestamp, and pointer to its parent(s) — the atomic unit of history.",
 "context": "Good commit hygiene (small, focused, well-described, each leaving the build green) is what makes history a usable tool rather than noise. In Git a commit is identified by the hash of its content, which is why history is tamper-evident.",
 "see_also": ["Git", "Branch", "Conventional Commits", "Atomic Commit"]},

{"term": "Branch", "branch": "Software Engineering", "tags": ["fundamental"], "wikipedia": "Branching (version control)",
 "def": "A divergent line of development. In Git, just a lightweight movable pointer to a commit — making branching and merging cheap.",
 "context": "Branching *strategy* is the real topic: trunk-based development (short-lived branches, merge often) vs Git Flow (long-lived release branches). The industry has largely swung to trunk-based + feature flags to avoid painful long-lived merges.",
 "see_also": ["Git", "Merge", "Rebase", "Trunk-based Development", "Feature Flag"]},

{"term": "Merge", "branch": "Software Engineering", "tags": [], "wikipedia": "Merge (version control)",
 "def": "Combining divergent branches, reconciling their changes — automatically where they don't overlap, with a **merge conflict** to resolve where they do.",
 "context": "A merge commit preserves the true branching history (two parents); the alternative, rebasing, rewrites for a linear history. Conflicts are inevitable on shared code; merging often and keeping branches short is how you keep them small.",
 "see_also": ["Branch", "Rebase", "Merge Conflict", "Three-way Merge"],
 "confused": [("Rebase", "Merge preserves history with a merge commit (true but messy); rebase replays your commits onto a new base for a clean linear history (tidy but rewrites).")]},

{"term": "Rebase", "branch": "Software Engineering", "tags": [], "wikipedia": "Rebasing (version control)",
 "def": "Reapplying a branch's commits onto a new base commit, producing a linear history as if you'd branched from the new point.",
 "context": "Cleaner history than merge, but it *rewrites* commits (new hashes) — hence the golden rule: never rebase commits you've already pushed and shared. Interactive rebase is also the tool for tidying local history (squash, reorder, reword) before review.",
 "see_also": ["Merge", "Commit", "Git", "Interactive Rebase", "Force Push"]},

{"term": "Semantic Versioning", "branch": "Software Engineering", "aliases": ["SemVer"],
 "tags": [], "wikipedia": "Software versioning",
 "def": "A versioning convention `MAJOR.MINOR.PATCH`: bump MAJOR for breaking changes, MINOR for backward-compatible features, PATCH for backward-compatible fixes.",
 "context": "A social contract so dependents know what an upgrade risks. Reality is messier — what counts as 'breaking' is fuzzy, and 'dependency hell' persists. SemVer paired with lockfiles is the practical compromise.",
 "see_also": ["Dependency", "Backward Compatibility", "Lockfile", "Dependency Hell"]},

{"term": "Dependency", "branch": "Software Engineering", "de": "Abhängigkeit", "tags": ["fundamental"], "wikipedia": "Coupling (computer programming)",
 "def": "External code your project relies on. The dependency *graph* — your deps, their deps, transitively — is what package managers resolve and what you ultimately ship and trust.",
 "context": "Every dependency is attack surface and maintenance burden (supply-chain attacks, left-pad, Log4Shell). Lockfiles pin exact versions for reproducibility; the cultural pendulum is swinging back toward fewer, more-trusted dependencies.",
 "see_also": ["Semantic Versioning", "Package Manager", "Supply Chain Attack", "Lockfile", "Transitive Dependency"]},

{"term": "Unit Test", "branch": "Software Engineering", "tags": ["fundamental"], "wikipedia": "Unit testing",
 "def": "An automated test exercising one small unit (a function/class) in isolation, fast and deterministic, verifying behaviour against expectations.",
 "context": "The base of the test pyramid — many fast unit tests, fewer integration, fewest end-to-end. Isolation often needs test doubles (mocks, stubs). The real payoff is regression safety and the design pressure: hard-to-test code is usually badly-coupled code.",
 "see_also": ["TDD", "Test Pyramid", "Mock", "Integration Test", "Code Coverage"]},

{"term": "TDD", "branch": "Software Engineering", "aliases": ["Test-Driven Development"],
 "tags": [], "wikipedia": "Test-driven development",
 "def": "A discipline of writing a failing test first, then the minimal code to pass it, then refactoring — the red-green-refactor loop.",
 "context": "As much a design technique as a testing one: writing the test first forces you to design the interface from the caller's view. Divisive in practice; even skeptics often concede it shines for well-specified logic and bug fixes (reproduce-then-fix).",
 "see_also": ["Unit Test", "Refactoring", "Red-Green-Refactor", "BDD"]},

{"term": "CI", "branch": "Software Engineering", "aliases": ["Continuous Integration"],
 "tags": ["fundamental"], "wikipedia": "Continuous integration",
 "def": "The practice of merging all developers' work to a shared mainline frequently, with each integration automatically built and tested.",
 "context": "The point is *frequency*: integrate small changes often so conflicts and breakages stay tiny and are caught in minutes. A running CI server is the enforcement mechanism. The natural partner to trunk-based development.",
 "see_also": ["CD", "CI/CD", "Build Pipeline", "Trunk-based Development", "Merge"]},

{"term": "SOLID", "branch": "Software Engineering", "tags": [], "wikipedia": "SOLID",
 "def": "Five OOP design principles: **S**ingle responsibility, **O**pen/closed, **L**iskov substitution, **I**nterface segregation, **D**ependency inversion.",
 "context": "A useful checklist for spotting brittle designs, though dogmatic application produces its own over-abstracted mess. Dependency inversion (depend on abstractions, not concretions) and single responsibility are the two that pay off most often.",
 "see_also": ["Dependency Injection", "Design Pattern", "Coupling", "Liskov Substitution Principle", "Inheritance"]},

{"term": "DRY", "branch": "Software Engineering", "aliases": ["Don't Repeat Yourself"],
 "tags": [], "wikipedia": "Don't repeat yourself",
 "def": "The principle that every piece of knowledge should have a single, authoritative representation in a system — avoid duplicating logic.",
 "context": "Easily over-applied: the counter-wisdom 'duplication is far cheaper than the wrong abstraction' (Sandi Metz) is the necessary corrective. DRY is about *knowledge*, not about textually-similar code that happens to coincide. Premature DRYing couples things that should stay independent.",
 "see_also": ["Coupling", "Abstraction", "WET", "Single Source of Truth"]},

{"term": "Coupling", "branch": "Software Engineering", "tags": [], "wikipedia": "Coupling (computer programming)",
 "def": "The degree of interdependence between modules — how much one must know about another. Low (loose) coupling is the goal.",
 "context": "The eternal pairing with cohesion: aim for loose coupling and high cohesion. Tight coupling is what makes a change in one place break things in five others. Most architectural patterns (interfaces, events, dependency injection) are coupling-reduction machinery.",
 "see_also": ["Cohesion", "Dependency Injection", "Interface", "Modularity"],
 "confused": [("Cohesion", "Coupling is *between* modules (want it low); cohesion is *within* a module (want it high — one module, one clear job).")]},

{"term": "Cohesion", "branch": "Software Engineering", "tags": [], "wikipedia": "Cohesion (computer science)",
 "def": "How focused a single module is — high cohesion means its parts all serve one well-defined purpose.",
 "context": "High cohesion makes code easy to name, find, and change; low cohesion is the 'utils.js with 40 unrelated functions' smell. Together with loose coupling, it's the two-word summary of good modular design.",
 "see_also": ["Coupling", "Single Responsibility Principle", "Modularity"]},

{"term": "Dependency Injection", "branch": "Software Engineering", "aliases": ["DI", "IoC"],
 "tags": [], "wikipedia": "Dependency injection",
 "def": "Supplying a component's dependencies from outside (via constructor or setter) rather than having it construct them itself — a form of inversion of control.",
 "context": "Decouples a class from *which* concrete implementation it uses, making it testable (inject a mock) and configurable. Frameworks (Spring, .NET DI) automate the wiring, sometimes to the point of magic; the core idea works fine by hand.",
 "see_also": ["Inversion of Control", "Coupling", "SOLID", "Mock", "Interface"]},

{"term": "Microservices", "branch": "Software Engineering", "tags": ["modern"], "wikipedia": "Microservices",
 "def": "An architectural style structuring an application as a suite of small, independently deployable services communicating over the network, each owning its data.",
 "context": "Trades in-process simplicity for organisational scalability — independent teams, deploys, and scaling. But it converts every method call into a distributed-systems problem (latency, partial failure, eventual consistency, observability). 'You must be this tall to ride.' Many teams over-adopted and walked back to a 'modular monolith'.",
 "see_also": ["Monolith", "Service Mesh", "Distributed System", "API", "Bounded Context"],
 "confused": [("Monolith", "Microservices: many independently deployed services (operational complexity). Monolith: one deployable unit (simpler ops, harder to scale teams).")]},

{"term": "Monolith", "branch": "Software Engineering", "tags": [], "wikipedia": "Monolithic application",
 "def": "An application built and deployed as a single unit, with all functionality in one codebase and process.",
 "context": "Long a pejorative, now partly rehabilitated: a well-structured 'modular monolith' avoids distributed-systems pain and is the right default until scale forces otherwise. 'Start with a monolith, extract services when a seam genuinely hurts' is the current consensus.",
 "see_also": ["Microservices", "Modular Monolith", "Bounded Context"]},

{"term": "Design Pattern", "branch": "Software Engineering", "de": "Entwurfsmuster", "tags": [], "wikipedia": "Software design pattern",
 "def": "A named, reusable solution to a recurring design problem — a shared vocabulary (Singleton, Observer, Factory, Strategy) rather than copy-paste code.",
 "context": "The Gang of Four catalogued the originals. Value lies more in the shared vocabulary than in rote application; some patterns are partly workarounds for missing language features (the Strategy pattern is just a first-class function elsewhere). Reach for them to *name* a solution you've arrived at, not to force structure.",
 "see_also": ["SOLID", "Anti-pattern", "Singleton", "Observer Pattern", "Factory Pattern"]},

{"term": "API", "branch": "Software Engineering", "aliases": ["Application Programming Interface"],
 "tags": ["fundamental"], "wikipedia": "API",
 "def": "The defined contract through which one piece of software is used by another — function signatures, endpoints, data formats. The interface, deliberately hiding the implementation.",
 "context": "Spans library APIs (function calls) to web APIs (REST/GraphQL over HTTP). A good API is hard to misuse and stable; once published it's a promise, which is why versioning and backward compatibility loom so large. 'API design is UX for developers.'",
 "see_also": ["ABI", "REST", "Interface", "Backward Compatibility", "API Versioning"],
 "confused": [("ABI", "An API is a source-level contract (compile against it); an ABI is a binary-level contract (link/run against it) — calling conventions, struct layout.")]},

{"term": "ABI", "branch": "Software Engineering", "aliases": ["Application Binary Interface"],
 "tags": [], "wikipedia": "Application binary interface",
 "def": "The binary-level contract between compiled components — calling conventions, data type sizes and alignment, struct layout, name mangling — so separately compiled code can link and run together.",
 "context": "Why you can swap a shared library (.so/.dll) without recompiling, as long as the ABI is stable. ABI breaks are nastier than API breaks: code compiles fine and then corrupts memory at runtime. C's stable ABI is why it's the universal FFI lingua franca.",
 "see_also": ["API", "Shared Library", "Calling Convention", "FFI", "Name Mangling"]},

{"term": "Library", "branch": "Software Engineering", "de": "Bibliothek", "tags": ["fundamental"], "wikipedia": "Library (computing)",
 "def": "A collection of reusable code you call from your program — *you* control the flow and call into it.",
 "context": "The inversion-of-control distinction from a framework is the thing worth knowing: with a library you're in charge and call it; with a framework, it's in charge and calls you ('don't call us, we'll call you').",
 "see_also": ["Framework", "API", "Dependency", "Shared Library", "Static Library"],
 "confused": [("Framework", "You call a library; a framework calls you. Libraries are tools you pick up; frameworks are structures you build inside.")]},

{"term": "Framework", "branch": "Software Engineering", "tags": ["fundamental"], "wikipedia": "Software framework",
 "def": "A reusable scaffold that defines the structure of your application and calls *your* code at the points it specifies — inversion of control.",
 "context": "More opinionated and more total than a library: it dictates architecture (Django, Rails, Spring, React). Picking one is a long-term commitment to its conventions and lifecycle. The tradeoff: speed and structure now vs. lock-in and 'fighting the framework' later.",
 "see_also": ["Library", "Inversion of Control", "Convention over Configuration", "Boilerplate"]},

# ============================ ALGORITHMS & DATA STRUCTURES ============================
{"term": "Array", "branch": "Algorithms & Data Structures", "de": "Feld", "tags": ["fundamental"], "wikipedia": "Array (data structure)",
 "def": "A contiguous block of memory holding elements of the same type, indexed in O(1) by position.",
 "context": "The most cache-friendly structure there is — contiguity means the CPU prefetcher loves it, often beating 'better' Big-O structures in practice. The cost: insertion/deletion in the middle is O(n), and fixed-size arrays need copying to grow (the dynamic-array doubling trick).",
 "see_also": ["Dynamic Array", "Linked List", "Cache", "Locality of Reference", "Big-O Notation"],
 "confused": [("Linked List", "Array: contiguous, O(1) random access, costly insert. Linked list: scattered nodes, O(1) insert at a known node, O(n) access, cache-hostile.")]},

{"term": "Linked List", "branch": "Algorithms & Data Structures", "tags": ["fundamental"], "wikipedia": "Linked list",
 "def": "A sequence of nodes where each holds a value and a pointer to the next (and maybe previous), so elements live scattered in memory.",
 "context": "O(1) insertion/deletion at a known position, but O(n) access and terrible cache behaviour (pointer-chasing). The textbook favourite that's often a poor real-world choice precisely because of memory locality — arrays usually win unless you need cheap splicing.",
 "see_also": ["Array", "Pointer", "Stack", "Queue", "Locality of Reference"]},

{"term": "Stack", "branch": "Algorithms & Data Structures", "de": "Stapel", "tags": ["fundamental"], "wikipedia": "Stack (abstract data type)",
 "def": "A LIFO (last-in, first-out) collection: push to add, pop to remove from the same end.",
 "context": "Everywhere: the call stack (function frames), expression evaluation, undo, backtracking, depth-first search. The abstract data type, distinct from 'the stack' (the call-stack region of memory) — though they're named for the same discipline.",
 "see_also": ["Queue", "Call Stack", "Recursion", "Depth-First Search"],
 "confused": [("Queue", "Stack is LIFO (last in, first out — like a stack of plates); queue is FIFO (first in, first out — like a line).")]},

{"term": "Queue", "branch": "Algorithms & Data Structures", "de": "Warteschlange", "tags": ["fundamental"], "wikipedia": "Queue (abstract data type)",
 "def": "A FIFO (first-in, first-out) collection: enqueue at the back, dequeue from the front.",
 "context": "The basis of breadth-first search, task scheduling, buffering, and message brokers. Variants abound: deque (both ends), priority queue (ordered by priority, usually a heap), ring buffer (fixed-size circular).",
 "see_also": ["Stack", "Priority Queue", "Heap", "Breadth-First Search", "Ring Buffer"]},

{"term": "Hash Table", "branch": "Algorithms & Data Structures", "aliases": ["Hash Map", "Dictionary"],
 "tags": ["fundamental"], "wikipedia": "Hash table",
 "def": "A structure mapping keys to values with average O(1) lookup, insert, and delete, by hashing the key to a bucket index.",
 "context": "The workhorse associative array behind every language's dict/map. The catches: collisions (handled by chaining or open addressing), worst-case O(n) when hashing degrades, and no ordering. Hash-flooding (deliberate collision DoS) is why some runtimes randomise hash seeds.",
 "see_also": ["Hash Function", "Collision", "Array", "Bloom Filter", "Load Factor"]},

{"term": "Tree", "branch": "Algorithms & Data Structures", "de": "Baum", "tags": ["fundamental"], "wikipedia": "Tree (data structure)",
 "def": "A hierarchical structure of nodes with a single root, where each node has children but exactly one parent — no cycles.",
 "context": "The shape of hierarchy everywhere: filesystems, the DOM, ASTs, org charts, decision trees. Balanced search trees give O(log n) operations; the difference between a balanced and a degenerate (linked-list-shaped) tree is the whole game.",
 "see_also": ["Binary Search Tree", "B-tree", "Heap", "Trie", "Graph", "Tree Traversal"]},

{"term": "Binary Search Tree", "branch": "Algorithms & Data Structures", "aliases": ["BST"],
 "tags": ["fundamental"], "wikipedia": "Binary search tree",
 "def": "A binary tree maintaining the invariant: left subtree keys < node key < right subtree keys — giving O(log n) search, insert, delete when balanced.",
 "context": "Degenerates to a linked list (O(n)) if you insert sorted data without balancing — which is why self-balancing variants (red-black, AVL) exist and back most ordered-map implementations. The in-order traversal yields sorted output for free.",
 "see_also": ["Tree", "Red-Black Tree", "B-tree", "Binary Search", "Self-balancing Tree"]},

{"term": "Heap", "branch": "Algorithms & Data Structures", "tags": ["fundamental"], "wikipedia": "Heap (data structure)",
 "def": "A tree-based structure maintaining the heap property (parent ≤ children for a min-heap), giving O(1) access to the min/max and O(log n) insert/extract.",
 "context": "The standard backing for a priority queue, and the heart of heapsort and Dijkstra's algorithm. Usually stored compactly in an array (no pointers — parent/child by index arithmetic). Distinct from 'the heap', the region of dynamically-allocated memory.",
 "see_also": ["Priority Queue", "Heapsort", "Tree", "Dijkstra's Algorithm"]},

{"term": "Graph", "branch": "Algorithms & Data Structures", "de": "Graph", "tags": ["fundamental"], "wikipedia": "Graph (abstract data type)",
 "def": "A set of **vertices** connected by **edges** (directed or undirected, weighted or not) — the general model for networks and relationships.",
 "context": "Models almost everything relational: social networks, road maps, dependencies, the web. Represented as an adjacency list (sparse) or matrix (dense). A huge family of algorithms (traversal, shortest path, flow, matching) builds on it; many real problems reduce to a known graph problem.",
 "see_also": ["Tree", "Breadth-First Search", "Depth-First Search", "Dijkstra's Algorithm", "Adjacency List", "Topological Sort"]},

{"term": "Trie", "branch": "Algorithms & Data Structures", "aliases": ["Prefix Tree"],
 "tags": [], "wikipedia": "Trie",
 "def": "A tree where each path from the root spells a string, sharing common prefixes — lookup is O(length of key), independent of how many keys are stored.",
 "context": "The structure behind autocomplete, spell-checkers, IP routing tables (radix tries), and prefix matching. Trades memory for prefix-search speed; compressed variants (radix/Patricia tries) cut the space cost.",
 "see_also": ["Tree", "Hash Table", "String", "Radix Tree"]},

{"term": "Big-O Notation", "branch": "Algorithms & Data Structures", "aliases": ["Asymptotic Notation"],
 "tags": ["fundamental"], "wikipedia": "Big O notation",
 "def": "A notation describing how an algorithm's resource use grows with input size *n*, ignoring constants and lower-order terms — the upper bound on growth rate.",
 "context": "The lingua franca for comparing algorithms, but the constants it discards matter in practice: an O(n) algorithm with a huge constant can lose to O(n log n) at real sizes, and cache effects routinely upend the theory. Use it to spot scaling cliffs (the O(n²) loop), not to micro-optimise.",
 "see_also": ["Time Complexity", "Space Complexity", "Amortized Analysis", "Algorithm"]},

{"term": "Time Complexity", "branch": "Algorithms & Data Structures", "tags": ["fundamental"], "wikipedia": "Time complexity",
 "def": "How an algorithm's running time scales with input size, expressed in Big-O — O(1), O(log n), O(n), O(n log n), O(n²), O(2ⁿ)…",
 "context": "The hierarchy to internalise: constant and log are great, linear and linearithmic are fine, quadratic hurts at scale, exponential is intractable past tiny inputs. Worst-case is the usual quote; average and amortised matter too (hash tables, dynamic arrays).",
 "see_also": ["Big-O Notation", "Space Complexity", "Amortized Analysis", "P vs NP"]},

{"term": "Space Complexity", "branch": "Algorithms & Data Structures", "tags": [], "wikipedia": "Space complexity",
 "def": "How an algorithm's memory use scales with input size, in Big-O terms.",
 "context": "The other half of the cost picture, and the constant tradeoff partner of time: memoisation and lookup tables buy speed with space; streaming and in-place algorithms save space at some time cost. In-place (O(1) extra space) is a prized property.",
 "see_also": ["Time Complexity", "Big-O Notation", "In-place Algorithm", "Memoization"]},

{"term": "Binary Search", "branch": "Algorithms & Data Structures", "tags": ["fundamental"], "wikipedia": "Binary search algorithm",
 "def": "Finding an element in a *sorted* array in O(log n) by repeatedly halving the search interval.",
 "context": "Deceptively easy to get wrong (off-by-one, overflow in the midpoint) — famously, most hand-written implementations have bugs. The general technique ('binary search on the answer') solves far more than array lookup: any monotonic predicate over a range.",
 "see_also": ["Binary Search Tree", "Time Complexity", "Sorting", "Divide and Conquer"]},

{"term": "Quicksort", "branch": "Algorithms & Data Structures", "tags": [], "wikipedia": "Quicksort",
 "def": "A divide-and-conquer sort that picks a pivot, partitions elements around it, and recurses — O(n log n) average, O(n²) worst case.",
 "context": "Usually the fastest comparison sort in practice thanks to good cache behaviour and in-place operation, despite the quadratic worst case (mitigated by randomised or median-of-three pivots). Real standard libraries often use introsort (quicksort that falls back to heapsort) or Timsort.",
 "see_also": ["Merge Sort", "Sorting", "Divide and Conquer", "Pivot", "Time Complexity"]},

{"term": "Breadth-First Search", "branch": "Algorithms & Data Structures", "aliases": ["BFS"],
 "tags": ["fundamental"], "wikipedia": "Breadth-first search",
 "def": "A graph traversal exploring all neighbours at the current depth before going deeper, using a queue.",
 "context": "Finds the shortest path in an *unweighted* graph (fewest edges), level by level. The queue-based counterpart to DFS's stack/recursion. Reach for it whenever 'fewest steps' is the question — maze solving, social-graph degrees of separation.",
 "see_also": ["Depth-First Search", "Graph", "Queue", "Shortest Path", "Dijkstra's Algorithm"],
 "confused": [("Depth-First Search", "BFS explores level by level (queue, finds shortest unweighted path); DFS plunges down one branch fully before backtracking (stack/recursion).")]},

{"term": "Depth-First Search", "branch": "Algorithms & Data Structures", "aliases": ["DFS"],
 "tags": ["fundamental"], "wikipedia": "Depth-first search",
 "def": "A graph traversal that explores as far as possible down one branch before backtracking, using a stack or recursion.",
 "context": "The basis of topological sort, cycle detection, connected components, and most backtracking. Lower memory than BFS on wide graphs, but doesn't find shortest paths. The recursive form is elegant; watch the stack depth on deep graphs.",
 "see_also": ["Breadth-First Search", "Graph", "Stack", "Recursion", "Topological Sort", "Backtracking"]},

{"term": "Dijkstra's Algorithm", "branch": "Algorithms & Data Structures", "tags": [], "wikipedia": "Dijkstra's algorithm",
 "def": "Finds the shortest path from a source to all vertices in a graph with non-negative edge weights, using a priority queue to always expand the nearest unvisited vertex.",
 "context": "The canonical weighted shortest-path algorithm (routing, maps). Fails with negative weights (use Bellman-Ford), and A* extends it with a heuristic to search faster toward a goal. A clean example of the greedy strategy done right.",
 "see_also": ["Graph", "Priority Queue", "Greedy Algorithm", "A* Search", "Shortest Path", "Heap"]},

{"term": "Dynamic Programming", "branch": "Algorithms & Data Structures", "aliases": ["DP"],
 "tags": [], "wikipedia": "Dynamic programming",
 "def": "Solving a problem by breaking it into overlapping subproblems and storing their solutions (memoisation or tabulation) to avoid recomputation.",
 "context": "Applies when a problem has optimal substructure *and* overlapping subproblems (the second is what separates it from plain divide-and-conquer). Turns exponential recursion into polynomial time — knapsack, edit distance, shortest paths. The hard part is always finding the right state and recurrence.",
 "see_also": ["Memoization", "Recursion", "Greedy Algorithm", "Optimal Substructure", "Divide and Conquer"]},

{"term": "Greedy Algorithm", "branch": "Algorithms & Data Structures", "tags": [], "wikipedia": "Greedy algorithm",
 "def": "An algorithm that makes the locally optimal choice at each step, hoping to reach a global optimum.",
 "context": "Beautifully simple and fast *when it works* — and proving it works (that local optima compose into a global one) is the catch. Correct for some problems (Dijkstra, Huffman, minimum spanning trees), wrong for others (the greedy knapsack), where DP is needed instead.",
 "see_also": ["Dynamic Programming", "Dijkstra's Algorithm", "Optimization", "Huffman Coding"]},

{"term": "Memoization", "branch": "Algorithms & Data Structures", "tags": [], "wikipedia": "Memoization",
 "def": "Caching a function's results keyed by its arguments, so repeated calls with the same inputs return instantly instead of recomputing.",
 "context": "The top-down face of dynamic programming, and a clean optimisation for any expensive *pure* function. Trades memory for time. Only safe when the function is pure (same inputs → same output, no side effects) — otherwise you cache stale or wrong results.",
 "see_also": ["Dynamic Programming", "Pure Function", "Cache", "Recursion"]},

{"term": "Bloom Filter", "branch": "Algorithms & Data Structures", "tags": [], "wikipedia": "Bloom filter",
 "def": "A space-efficient probabilistic structure that tests set membership with possible false positives but no false negatives — 'definitely not present' or 'probably present'.",
 "context": "When 'might be there' is good enough and memory is tight: databases skip disk lookups for definitely-absent keys, caches and CDNs avoid useless fetches. You can tune the false-positive rate against size, but you can't delete elements (counting variants can).",
 "see_also": ["Hash Function", "Hash Table", "Probabilistic Data Structure", "Cache"]},

# ============================ THEORY OF COMPUTATION ============================
{"term": "Turing Machine", "branch": "Theory of Computation", "tags": ["fundamental"], "wikipedia": "Turing machine",
 "def": "An abstract machine — an infinite tape, a head that reads/writes symbols, and a state table — that formalises what it means to 'compute'. The reference model for computability.",
 "context": "Not a blueprint for real computers but a definition of the computable: anything a Turing machine can compute is, by the Church-Turing thesis, what 'computable' *means*. 'Turing-complete' (a system that can simulate one) is the bar real languages clear — and accidentally so do things like SQL, TeX, and Magic: The Gathering.",
 "see_also": ["Church-Turing Thesis", "Halting Problem", "Turing Completeness", "Lambda Calculus", "Decidability"]},

{"term": "Finite State Machine", "branch": "Theory of Computation", "aliases": ["FSM", "Finite Automaton"],
 "tags": ["fundamental"], "wikipedia": "Finite-state machine",
 "def": "A computational model with a finite number of states and transitions triggered by inputs — no memory beyond the current state.",
 "context": "Far more practical than its theory billing: protocol handlers, UI flows, regex engines, lexers, and game AI are all FSMs. The limit (finite memory, can't count arbitrarily) is exactly why it can't match balanced parentheses — the reason regular expressions can't parse HTML.",
 "see_also": ["Regular Expression", "Turing Machine", "Pushdown Automaton", "Chomsky Hierarchy", "Lexer"]},

{"term": "Regular Expression", "branch": "Theory of Computation", "aliases": ["Regex", "Regexp"],
 "tags": ["fundamental"], "wikipedia": "Regular expression",
 "def": "A pattern language describing sets of strings, formally equivalent to a finite automaton — and in practice the everyday tool for text matching.",
 "context": "The theory (regular languages = FSM-recognisable) explains the famous limits: classic regex can't match nested structures, so 'don't parse HTML with regex'. Real-world engines add backreferences (beyond regular) at the cost of catastrophic backtracking — a genuine ReDoS attack vector.",
 "see_also": ["Finite State Machine", "Context-free Grammar", "Chomsky Hierarchy", "Lexer", "ReDoS"]},

{"term": "Context-free Grammar", "branch": "Theory of Computation", "aliases": ["CFG"],
 "tags": [], "wikipedia": "Context-free grammar",
 "def": "A set of production rules powerful enough to describe nested, recursive structure (balanced brackets, arithmetic expressions) — recognised by a pushdown automaton.",
 "context": "The formalism behind nearly every programming language's syntax and the parsers that read it. One step up the Chomsky hierarchy from regular languages — the added power (a stack) is precisely what lets it handle nesting that regex cannot.",
 "see_also": ["Regular Expression", "Pushdown Automaton", "Parser", "Chomsky Hierarchy", "AST", "Backus-Naur Form"]},

{"term": "Halting Problem", "branch": "Theory of Computation", "de": "Halteproblem", "tags": ["fundamental"], "wikipedia": "Halting problem",
 "def": "The problem of deciding, for an arbitrary program and input, whether it will eventually halt or run forever — proven by Turing to be **undecidable**: no general algorithm can solve it for all cases.",
 "context": "The foundational impossibility result, and a practical ceiling, not just a curiosity: it's *why* perfect static analysis, exhaustive bug detection, and total termination checking can't exist in general. Many real questions reduce to it (Rice's theorem generalises the gloom to all non-trivial semantic properties).",
 "see_also": ["Turing Machine", "Decidability", "Church-Turing Thesis", "Rice's Theorem", "Undecidable Problem"],
 "links": ["[The Halting Problem explained — Computerphile](https://www.youtube.com/watch?v=macM_MtS_w4)"]},

{"term": "Church-Turing Thesis", "branch": "Theory of Computation", "tags": [], "wikipedia": "Church–Turing thesis",
 "def": "The hypothesis that any function 'effectively computable' by any means is computable by a Turing machine — equating the intuitive notion of computation with the formal one.",
 "context": "A thesis, not a theorem (it relates an informal idea to a formal model, so it can't be proved), but universally accepted. Its force: every reasonable model of computation devised — lambda calculus, recursive functions, real CPUs — has turned out exactly equivalent in power.",
 "see_also": ["Turing Machine", "Lambda Calculus", "Turing Completeness", "Computability"]},

{"term": "P vs NP", "branch": "Theory of Computation", "tags": ["fundamental"], "wikipedia": "P versus NP problem",
 "def": "The open question of whether every problem whose solution can be *verified* quickly (NP) can also be *solved* quickly (P) — i.e. does P = NP?",
 "context": "The most famous open problem in computer science (a Clay Millennium Prize). Almost everyone believes P ≠ NP. The stakes are enormous: if P = NP, most modern cryptography would collapse and optimisation would transform. Until then, NP-hardness is the practical signal to stop seeking an exact polynomial algorithm and use heuristics.",
 "see_also": ["NP-complete", "NP-hard", "Time Complexity", "Reduction", "Cryptography"]},

{"term": "NP-complete", "branch": "Theory of Computation", "tags": [], "wikipedia": "NP-completeness",
 "def": "The hardest problems in NP: in NP themselves, and every NP problem reduces to them — so a fast solution to one would solve them all (and prove P = NP).",
 "context": "The practical takeaway is recognition, not theory: if your problem is NP-complete (SAT, travelling salesman decision, graph colouring, knapsack), stop looking for an efficient exact algorithm and reach for approximation, heuristics, or constraint solvers. Recognising a disguised NP-complete problem saves weeks.",
 "see_also": ["P vs NP", "NP-hard", "Reduction", "SAT", "Approximation Algorithm"],
 "confused": [("NP-hard", "NP-complete = NP-hard *and* in NP (verifiable quickly). NP-hard problems are at least as hard but needn't be in NP — the halting problem is NP-hard but not NP-complete.")]},

{"term": "NP-hard", "branch": "Theory of Computation", "tags": [], "wikipedia": "NP-hardness",
 "def": "Problems at least as hard as the hardest problems in NP — every NP problem reduces to them — but not necessarily *in* NP themselves.",
 "context": "Broader than NP-complete: an NP-hard problem need not even be decidable. The label is the red flag that exact efficient solutions are (almost certainly) off the table, pushing you toward approximation or heuristics.",
 "see_also": ["NP-complete", "P vs NP", "Reduction", "Halting Problem"]},

{"term": "Lambda Calculus", "branch": "Theory of Computation", "tags": [], "wikipedia": "Lambda calculus",
 "def": "A formal system of computation built entirely from function definition and application — Turing-complete using nothing but anonymous functions.",
 "context": "Church's model, equivalent in power to Turing machines but functional rather than imperative. The theoretical bedrock of functional programming: lambdas, closures, currying, and type systems all trace back here. Proof that you can compute anything with just functions.",
 "see_also": ["Turing Machine", "Church-Turing Thesis", "Lambda", "Functional Programming", "Currying"]},

{"term": "Decidability", "branch": "Theory of Computation", "tags": [], "wikipedia": "Decidability (logic)",
 "def": "A problem is **decidable** if an algorithm exists that always halts with a correct yes/no answer; **undecidable** if no such algorithm can exist for all inputs.",
 "context": "The sharp line between 'a computer can in principle solve this' and 'no it can't, ever'. The halting problem is the canonical undecidable one. Distinct from intractable (decidable but too slow, like NP-hard) — undecidable means *impossible*, not just expensive.",
 "see_also": ["Halting Problem", "Turing Machine", "Rice's Theorem", "P vs NP", "Computability"]},

{"term": "Chomsky Hierarchy", "branch": "Theory of Computation", "tags": [], "wikipedia": "Chomsky hierarchy",
 "def": "A four-level classification of formal grammars by expressive power: regular ⊂ context-free ⊂ context-sensitive ⊂ recursively enumerable, each recognised by a more powerful machine.",
 "context": "The unifying map of the whole field: it ties grammar classes to the machines that recognise them (regular↔FSM, context-free↔pushdown automaton, unrestricted↔Turing machine). Explains *why* regex can't parse nested code and why language design picks a grammar level deliberately.",
 "see_also": ["Regular Expression", "Context-free Grammar", "Finite State Machine", "Pushdown Automaton", "Turing Machine"]},
]
